      answer_line: 'If you loved The Night Circus for its immersive prose, rivals-to-lovers romance, and sense of impossible wonder, start with The Starless Sea, Piranesi, and Caraval.',
      why_people_love: "The Night Circus is not primarily about plot — readers who come to it for escalating stakes tend to be disappointed. What Morgenstern offers is atmosphere so immersive it reads like a sensory experience: caramel and woodsmoke, the black-and-white aesthetic of Le Cirque des Rêves, the quality of a world that exists outside ordinary time. The romance between Celia and Marco works because their love is expressed through creation — each new tent is a message to the other — which is a more interesting foundation than most fantasy romances manage. The non-linear structure, jumping between 1873 and 1902, rewards attention rather than punishing it. If you came for the wonder and stayed for the melancholy, that is what this book is actually about.",
