      why_people_love: "The City of Brass does something that feels rarer than it should: it builds a fantasy world from Islamic mythology rather than European folklore, and treats the djinn not as wish-granters but as a complex civilization with ethnic divisions, religious factions, and politics fermenting for thousands of years. Nahri is a Cairo street healer and con artist who doesn't believe in her own gifts — and when she accidentally summons Dara, a djinn warrior with a past she's not ready for, the book becomes a story about an ordinary person surviving in a world she has no frame for. The political intrigue deepens significantly across the trilogy, with the second volume being many readers' favourite, so the series investment is front-loaded but worth it.",
