      why_people_love: "Best Served Cold is one of the few fantasy novels that takes revenge seriously as a subject — not as catharsis, but as a process with costs. Monza Murcatto assembles a crew of the damaged and the desperate to kill seven men, and Abercrombie documents every killing with the care of a writer who understands that each one makes her less of what she was. The book works on two levels simultaneously: as an extremely satisfying revenge narrative — the crew dynamics, the planning, the execution — and as a slow dismantling of that satisfaction, so that by the end nobody has received what they wanted, including the reader. Caul Shivers arriving in Styria to become a better man and leaving it as something worse is the most affecting character arc Abercrombie has written. Reads completely standalone; prior First Law knowledge adds texture but nothing essential.",
