      angle: 'An Intimate Family Story That Becomes a War Novel',
      answer_line: "If you loved The Sword of Kaigen for its elemental combat, Misaki's slow reclamation of herself, and the quiet domestic story that erupts into devastating war, start with The Poppy War, Circe, and Jade City.",
      why_people_love: "The Sword of Kaigen begins almost as a domestic novel. Misaki is a warrior woman who has spent years being the perfect wife and mother in Kaigen, a village of elite jijakalu fighters who channel water and ice through breath and focus. She was extraordinary once. She made herself smaller. Wang's first half is the slow, precise work of showing you exactly what she buried — and what it cost her. Then the outside world arrives, her son discovers the empire's history is fabricated, and the second half erupts into the kind of war violence and loss you don't recover from. The elemental combat is written with a physical specificity that makes every fight feel different. The darkness is earned. The ending doesn't rescue you. For a self-published debut, this is one of the most technically assured fantasy novels of the last decade.",
