      answer_line: "If you loved The Fifth Season for its second-person narration, its world where oppression is geology, and Essun's grief driving everything, start with The Poppy War, Kindred, and Piranesi.",
      why_people_love: "The Fifth Season opens with a mother, a dead child, and the end of the world — in that order of importance. Jemisin builds the Stillness, a supercontinent that regularly tries to kill everyone who lives on it, and then reveals that the society's response to apocalypse has always been to enslave the people best equipped to survive it. Orogenes — people who can manipulate seismic energy — are taken from their families as children, trained in the Fulcrum, and used as weapons and shock absorbers for a civilisation that hates what they are. The second-person narration (you do this, you feel that) is the most debated technical choice in recent fantasy; it is also the most earned — what it reveals in the final pages changes what you understood to be happening on every page before. Three consecutive Hugo wins. The darkest fantasy novel on this list that is also, somehow, about hope.",
