      why_people_love: "The Heroes takes place entirely over three days on one battlefield — a circle of standing stones called, with full Abercrombie irony, 'the Heroes.' Union soldiers and Northmen are killing each other over a patch of ground that neither side will hold by the end. Abercrombie rotates through POVs with surgical precision: the aging named man trying to retire with his conscience intact, the disgraced knight who is brilliant at killing and broken in every other way, the cowardly prince scheming his way through a war he didn't want to fight, the young soldier learning what glory actually smells like. Nothing is resolved. The politicians who sent them are fine. The battle achieves nothing its participants intended. It is the most explicitly anti-war fantasy novel ever written, and it is also one of the most gripping. Ideally read after the original First Law trilogy and Best Served Cold, though it stands alone.",
