      answer_line: 'If you loved Discworld for its wit, its satire, or the warmth beneath the jokes, start with Good Omens, Jonathan Strange & Mr Norrell, and The House in the Cerulean Sea.',
      why_people_love: "Terry Pratchett was the most widely read British author of the 20th century for a reason that takes reading him to understand: the jokes are real jokes, the satire is precise, and the compassion is genuine. Discworld starts as a parody of fantasy and grows, over 41 books, into a complete civilisation — Ankh-Morpork as a lens on every human institution from war to money to journalism to death itself. The early books are lightweight parody; by Guards! Guards! the series has found something deeper. Sam Vimes is angry in the right direction. Granny Weatherwax does what has to be done. Death is the most humane character in any fantasy series. Pratchett was writing while dying of early-onset Alzheimer's and his last books argue, with furious wit, for the value of human dignity. All 41 novels are published.",
