            author: 'Douglas Adams',
            cover_url: 'https://covers.openlibrary.org/b/isbn/9780345391803-L.jpg',
            darkness_level: 1,
            heat_level: null,
            standalone: false,
            series: "The Hitchhiker's Guide to the Galaxy",
            series_number: 1,
