      angle: 'The most ambitious fantasy series ever written — ten books, gods, soldiers, and 300,000 years of history',
      answer_line: 'If you loved Malazan for its soldiers, its gods, or its refusal to explain itself, start with The Black Company, The Way of Kings, and The Darkness that Comes Before.',
      why_people_love: "Malazan drops you into the middle of a campaign on a continent you don't know, with characters whose history you haven't been given, and it does not apologise. The first hundred pages of Gardens of the Moon are genuinely disorienting — push through them. What waits on the other side is unlike anything else in fantasy: gods who are exhausted, soldiers who keep showing up despite everything, civilisations that rise and fall as background noise, and a moral philosophy — stated most clearly in the figure of Itkovian — that insists on witnessing the suffering of others even when it costs you everything. The body count is enormous and the darkness is real, but the series' deepest register is compassion. No other fantasy series has earned its readers' grief the way Malazan has. All ten main books are published.",
