      answer_line: 'If you loved A Deadly Education for El\'s voice, the Scholomance\'s brutal logic, or the enclave politics, start with Ninth House, The Magicians, and Babel.',
      why_people_love: "El Higgins is prophesied to cause mass death, has the power to do it, and has absolutely no intention of fulfilling any destiny. The Scholomance has no teachers and no staff — just students, monsters, and the brutal arithmetic of survival odds. Novik's masterstroke is El's voice: furious, precise, wickedly funny, and utterly self-aware about every trope she's being asked to inhabit. The trilogy uses the magic school setting to do serious work on class and privilege — the enclave families who've rigged the system versus the indie students who die at higher rates because they have no safety net. The series escalates dramatically: book 1 is tight and sharp, book 3 is world-scale. The trilogy completed in 2022.",
